import{z as o,x as s,o as e,c as n,q as t,j as r,D as E,d as l,s as A,S as B}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"失效分析 TEM / FIB","description":"","frontmatter":{"title":"失效分析 TEM / FIB","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/failure-analysis-tem-fib.md","filePath":"litho/failure-analysis-tem-fib.md","lastUpdated":1791413859000}'),p={name:"litho/failure-analysis-tem-fib.md"};function d(T,a,h,F,_,m){const i=s("Mermaid");return e(),n("div",null,[a[2]||(a[2]=t('<h1 id="失效分析-tem-fib" tabindex="-1">失效分析 TEM / FIB <a class="header-anchor" href="#失效分析-tem-fib" aria-label="Permalink to &quot;失效分析 TEM / FIB&quot;">​</a></h1><div class="epigraph"><p>顶视 SEM 看见的是投影；FIB 切开、TEM 看原子衬度，才把桥、虚空、偏 via 和损伤层从猜测变成剖面事实。</p><footer>—— 对照半导体失效分析中 FIB 制样与 TEM 的公开方法；JEOL / 产线 FA 通称</footer></div><p><a href="/litho/reliability-patterning-defects">上一课</a>把寿命写成几何代理。缺口是取证：探针失败或可靠性失败的那颗管芯，剖面究竟是 OPC 桥、刻蚀底切、via 未对准还是填充虚空。本课钉 FIB/TEM 在图形化链上的位置，并结束「集成、控制与良率」。节点怎么命名、钱怎么算，交给下一课程第一课<a href="/litho/node-naming">节点命名与实际尺寸</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>FIB（聚焦离子束）定点切开失败位，做成 TEM 薄片。TEM 给侧壁角、底脚、via 覆盖、硬掩模剩余、损伤层厚度。顶视 CD 合格的失效，往往在这里分叉：覆盖为零、弓形腰斩、或随机孔未打开。样本少而贵，不能当 APC 计量，但能校准「LRC 代理是否撒谎」。</p><p><span class="marginnote">TEM（透射电镜）让电子束穿过一片约几十纳米厚的薄片成像，能看原子级衬度；FIB（聚焦离子束）像一把纳米刻刀，用镓离子在指定地点切出这样一片薄片。一个是眼睛、一个是刀，合起来才完成一次「剖面取证」。</span></p><p>缺口是<strong>把 FA 接回模型版本</strong>，不是写电镜光学。一次 TEM 应能关闭 Pareto 上的一类，并触发 OPC/食谱/规则之一，而不是只进相册。</p>',7)),(e(),r(B,null,{default:E(()=>[A(i,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20LR%0A%20%20T%5B%22%E9%A1%B6%E8%A7%86%20CD%20%E5%90%88%E6%A0%BC%E7%9A%84%E5%A4%B1%E6%95%88%22%5D%20--%3E%20X%5B%22FIB%2FTEM%20%E5%89%96%E9%9D%A2%22%5D%0A%20%20X%20--%3E%20O1%5B%22via%20%E8%A6%86%E7%9B%96%E4%B8%BA%E9%9B%B6%20%E2%86%92%20%E5%A5%97%E5%88%BB%E9%97%AE%E9%A2%98%22%5D%0A%20%20X%20--%3E%20O2%5B%22%E8%85%B0%E8%BA%AB%E5%BC%93%E5%BD%A2%20%E2%86%92%20%E5%88%BB%E8%9A%80%20%2F%20%E8%83%B6%E5%89%96%E9%9D%A2%22%5D%0A%20%20X%20--%3E%20O3%5B%22%E5%A1%AB%E5%85%85%E8%99%9A%E7%A9%BA%20%E2%86%92%20%E6%B2%89%E7%A7%AF%E5%B7%A5%E8%89%BA%22%5D%0A%20%20X%20--%3E%20O4%5B%22%E9%9D%9E%E6%99%B6%E5%B1%82%E4%BC%AA%E5%BD%B1%20%E2%86%92%20%E5%88%B6%E6%A0%B7%E6%8D%9F%E4%BC%A4%2C%20%E5%88%AB%E5%91%8A%E6%88%90%E7%BC%BA%E9%99%B7%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p>这张图回答的是：顶视看不出的失效在剖面里分岔成哪几类根因——同一种「电学坏了」，剖面对应四种完全不同的责任工序。</p><h3 id="制样也是工艺" tabindex="-1">制样也是工艺 <a class="header-anchor" href="#制样也是工艺" aria-label="Permalink to &quot;制样也是工艺&quot;">​</a></h3><p>离子减薄会损伤、镀层会改衬度、定位误差会切错 via。FA 结论要含切面是否过特征中心。EUV 胶剖面更难，常看 AEI 后硬掩模。</p><p><span class="marginnote">FA 选件有偏：只切最惨的管芯，会高估系统严重度。应与失效模式的统计抽样计划一起设计。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>流程：电学定位 → 检测/复检坐标 → FIB 标记 → TEM → 分类回写（系统桥 / 套刻 / 填充 / 损伤）。与计量：TEM 锚 CD-SEM 偏置（匹配课的低频真值）。与 3D 胶模型：截面是校准集，不是全芯片。周期：SRAM 阵列适合做有代表性的切。</p><p>每份 TEM 报告应指向本课程已有机制中的一条，并给出关闭动作（改核、改食谱、改规则、或确认是个案颗粒）。没有动作的相册不算学习。半导体 FA 的 FIB/TEM 方法是工具；闭环才是本课的课点。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>顶视把三维投影成边；失效往往是 z 向的（未打穿、虚空、底切）。TEM 衍射与 Z 衬度区分材料。FIB 的 Ga 注入可能被误读为损伤，要用低损伤制样或等离子体 FIB。结论必须映射到本课程已有的机制：钝化、ARDE、套刻树、随机打开。</p><p><span class="marginnote">顶视像只看大楼外立面猜裂缝，FIB 加 TEM 像把楼切开一个观察断面：裂缝从哪层开始、有没有贯穿，一眼见分晓。代价是楼切开就废了——样本一次性、位置要一次选对，这正是 FA 贵而慢的原因。</span></p>',10)),(e(),r(B,null,{default:E(()=>[A(i,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20FAIL%5B%22%E7%94%B5%E5%AD%A6%20%2F%20%E5%8F%AF%E9%9D%A0%E6%80%A7%E5%A4%B1%E8%B4%A5%22%5D%20--%3E%20LOC%5B%22%E5%AE%9A%E4%BD%8D%22%5D%0A%20%20LOC%20--%3E%20FIB%5B%22FIB%20%E5%AE%9A%E7%82%B9%E5%88%87%E7%89%87%22%5D%0A%20%20FIB%20--%3E%20TEM%5B%22%E5%89%96%E9%9D%A2%E4%BA%8B%E5%AE%9E%22%5D%0A%20%20TEM%20--%3E%20CLS%5B%22%E5%85%B3%E9%97%AD%E4%B8%80%E7%B1%BB%20Pareto%22%5D%0A%20%20CLS%20--%3E%20ACT%5B%22OPC%20%2F%20%E9%A3%9F%E8%B0%B1%20%2F%20%E8%A7%84%E5%88%99%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p>TEM 关闭的是 Pareto 上的一类，并校准顶视代理。没有动作的截面相册不算学习。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>FA 不是量产计量，吞吐不允许。不发明未公开的原子像「标准图谱」。下一课程改谈节点经济，不再切薄片。</p><p><span class="marginnote">初学者容易把 FIB 切面边缘的「损伤层」当成工艺缺陷。镓离子注入与非晶化是制样自身的副作用；结论里必须写明切面是否过特征中心与制样条件，否则会把工具的痕迹告成电路的罪。</span></p><p>后课默认：关键失效模式要有 TEM 锚，代理规则才可信。图形化课程序列在此交给路线图与成本。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>FIB/TEM 把顶视猜测收成剖面，用于关闭 Pareto 类并校准代理。</li><li>样本少、有偏，不能进 APC。</li><li>制样损伤要进结论的不确定度。</li><li>出处：半导体 FA 中 FIB/TEM 公开方法；与计算光刻/刻蚀剖面的校准关系。</li></ul>',7))])}const c=o(p,[["render",d]]);export{D as __pageData,c as default};
